<div class='dvp dv-ops'><h4>${ic('history',18)} آخر العمليات</h4>${S.log.slice(0,4).map(l=>`<div class=op><b>${esc(l.a)}</b> ${esc(l.d)}<small>${new Date(l.t).toLocaleString('ar-EG')}</small></div>`).join('')||'<p class=mut>لا توجد عمليات بعد</p>'}</div>
